exports.text:
import { SourceFile, SyntaxKind } from 'ts-morph';
import { resolveModuleSpecifier } from './helpers';
import type { ExportInfo } from './schemas';

/**
 * analyzeExports variable - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
export const analyzeExports = (sourceFile: SourceFile) => {
  const exports: ExportInfo[] = [];

  // Export declarations (export ...)
  sourceFile.getExportDeclarations().forEach(exportDecl => {
    const rawModuleSpecifier = exportDecl.getModuleSpecifierValue();
    const moduleSpecifier = rawModuleSpecifier
      ? resolveModuleSpecifier(sourceFile, rawModuleSpecifier)
      : undefined;
    const exportText = exportDecl.getText();

    // Named exports
    const namedExports = exportDecl.getNamedExports();
    namedExports.forEach(namedExport => {
      const aliasNode = namedExport.getAliasNode();
      const name = aliasNode
        ? aliasNode.getText()
        : namedExport.getName();
      exports.push({
        name,
        kind: 'named',
        text: exportText,
        moduleSpecifier,
      });
    });

    // Namespace export (export * from '...' or export * as ns from '...')
    if (exportDecl.isNamespaceExport()) {
      const namespaceExport = exportDecl.getNamespaceExport();
      exports.push({
        name: namespaceExport ? namespaceExport.getName() : '*',
        kind: 'namespace',
        text: exportText,
        moduleSpecifier,
      });
    }
  });

  // Export assignments (export = ...)
  sourceFile.getExportAssignments().forEach(exportAssignment => {
    if (exportAssignment.isExportEquals()) {
      exports.push({
        name: 'default',
        kind: 'default',
        text: exportAssignment.getText(),
      });
    }
  });

  // Exported declarations (export function, export class, etc.)
  sourceFile.getExportedDeclarations().forEach((declarations, name) => {
    declarations.forEach(decl => {
      let declarationKind: ExportInfo['declarationKind'];

      if (decl.getKind() === SyntaxKind.FunctionDeclaration) {
        declarationKind = 'function';
      } else if (decl.getKind() === SyntaxKind.ClassDeclaration) {
        declarationKind = 'class';
      } else if (decl.getKind() === SyntaxKind.InterfaceDeclaration) {
        declarationKind = 'interface';
      } else if (decl.getKind() === SyntaxKind.TypeAliasDeclaration) {
        declarationKind = 'type';
      } else if (decl.getKind() === SyntaxKind.VariableDeclaration) {
        declarationKind = 'variable';
      } else if (decl.getKind() === SyntaxKind.EnumDeclaration) {
        declarationKind = 'enum';
      }

      exports.push({
        name,
        kind: name === 'default' ? 'default' : 'named',
        text: decl.getText(),
        declarationKind,
      });
    });
  });

  return exports;
};

