import edit from 'edit-json-file';
import { JsonEditor } from 'edit-json-file';
import { unlinkSync } from 'fs';
import { join } from 'path';
import { FILES_PROPERTY, PATH_PROPERTY } from '../constants';
import { consoleStars, getFolderPath, transformModule } from '../helpers';
import { CodebaseAnalysis, FileAnalysis } from '../schemas';

/**
 * Resolves the module specifiers for a list of file analysis entries,
 * mapping which files import which other files within the codebase.
 *
 * @param entries - List of all entries to analyze imports from.
 * @param files - List of codebase file keys to track and resolve modules against.
 * @returns An array of tuples mapping each entry key to the list of resolved codebase file keys it imports.
 */
const transformModules = (
  entries: [string, FileAnalysis][],
  ...files: string[]
) => {
  const cwd = process.cwd();
  const out = entries
    .map(
      ([key, { imports, relativePath }]) =>
        [key, relativePath, imports] as const,
    )
    .map(([key, relativePath, imports]) => {
      const specifiers = imports
        .map(({ moduleSpecifier }) => {
          return transformModule({
            cwd,
            relativePath,
            moduleSpecifier,
          });
        })
        .map(_path => [_path, `${_path}/index`]) // Add */index variants
        .flat()
        .filter(s => files.includes(s));

      return [key, Array.from(new Set(specifiers))] as const;
    });

  return out;
};

/**
 * Safely removes files from the project configuration and deletes them from disk.
 * Before deletion, it performs dependency checks to ensure that no file slated for removal
 * is imported by other files remaining in the codebase.
 *
 * @param CODEBASE_ANALYSIS - The full codebase analysis object.
 * @param jsonConfigPath - The relative path to the codebase JSON configuration file.
 * @param paths - The target file paths or directory prefixes to remove.
 * @returns True if files were successfully deleted and config updated; false if deletion errors occur.
 */
/**
 * remove variable - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
export const remove = (
  CODEBASE_ANALYSIS: CodebaseAnalysis,
  jsonConfigPath: string,
  ...paths: string[]
) => {
  const isEmpty = paths.length === 0;
  if (isEmpty) return console.warn('No files specified for removal.');
  try {
    const cwd = process.cwd();
    const json = join(cwd, jsonConfigPath);
    let file: JsonEditor | undefined = edit(json);

    if (!file) return;

    const root = getFolderPath(file.get(PATH_PROPERTY) as string);
    const files = file.get(FILES_PROPERTY) as string[];

    const entries2 = Object.entries(CODEBASE_ANALYSIS).filter(([key]) =>
      files.includes(key),
    );

    const entries = entries2.filter(([key]) =>
      paths.some(p => key.startsWith(p)),
    );

    // Check dependencies before deletion
    const safesToRemove: string[] = [];
    const cannotsRemove: [string, string[]][] = [];

    entries.forEach(([key]) => {
      const modules = transformModules(entries2, ...files);
      const importedFroms = modules
        .filter(([, specifiers]) => specifiers.includes(key))
        .map(([k]) => k);

      const check = importedFroms.length > 0;

      console.log('modules', '=>', importedFroms);
      console.log('key', '=>', key);

      if (check) return cannotsRemove.push([key, importedFroms]);
      return safesToRemove.push(key);
    });

    consoleStars();
    console.log(`🔧 Deletion of files (${entries.length} files)...`);

    // Display files that cannot be deleted
    if (cannotsRemove.length > 0) {
      const len = cannotsRemove.length;
      const one = 'file cannot be deleted (imported in other files)';
      const many = 'files cannot be deleted (imported in other files)';

      console.warn(`⚠️  ${len} ${len === 1 ? one : many} :`);
      cannotsRemove.forEach(([key, modules]) => {
        console.warn(`  - ⚠️  ${key} imported by:`);
        modules.forEach(m => console.warn(`    -> 📌 ${m}`));
      });
    }

    if (safesToRemove.length === 0) {
      console.warn('❌ No files can be deleted.');
      return consoleStars();
    }

    const formatteds = safesToRemove.map(key => {
      const _path = CODEBASE_ANALYSIS[key].relativePath;
      const absolute = join(root, _path);
      return [key, absolute] as const;
    });

    console.log(`🗑️ Deleting files (${safesToRemove.length} files)...`);

    let success = 0;
    const length = formatteds.length;

    formatteds.forEach(([key, path]) => {
      try {
        unlinkSync(path);
        console.log(`  - 🗑️ ${key}`);
        file?.set(
          FILES_PROPERTY,
          files.filter(key1 => key1 !== key),
        );
        success++;
      } catch {
        console.error(`  - ❌ Error, ${key} :`);
      }
    });

    file.save();
    console.log(`🗑️ Files deleted! (${success}/${length})`);
    file = undefined;
  } catch {
    console.error(`❌ Error while deleting files`);
    consoleStars();
    return false;
  }
  consoleStars();
  return true;
};

functions/softInit.text:
import editJsonFile from 'edit-json-file';
import { existsSync, mkdirSync, readFileSync } from 'fs';
import { join, relative } from 'path';
import { DEFAULT_CLI_NAME, DEFAULT_PATH_KEY, PROPERTIES } from '../constants';
import { createTypesStructure, getFolderPath } from '../helpers';
import { CodebaseAnalysis } from '../schemas';
import type { InitOptions } from './init';

/**
 * Performs a "soft" initialization of the codebase workspace.
 * It verifies that the config file, tsconfig path mapping, and folder path
 * already exist and are configured correctly. If they are, it recreates
 * the typescript types folder structure using current codebase analysis without
 * rewriting the configuration files.
 *
 * @param CODEBASE_ANALYSIS - The full codebase analysis object.
 * @param options - Options for soft initializing the project (reuses InitOptions layout).
 * @param options.root - Target directory for generated type files.
 * @param options.json - Target filepath for the codebase JSON config file.
 * @param options.path - The tsconfig compiler path alias key. Defaults to '#bemedev/*'.
 * @param options.bin - The CLI command binary name used in logging. Defaults to 'bemedev'.
 * @returns True if soft initialization passes and types are updated successfully; false if any prerequisite is missing or if type generation fails.
 */
/**
 * softInit variable - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
export const softInit = (
  CODEBASE_ANALYSIS: CodebaseAnalysis,
  {
    root,
    json,
    path = DEFAULT_PATH_KEY,
    bin = DEFAULT_CLI_NAME,
  }: InitOptions,
) => {
  const cwd = process.cwd();
  const configFile = join(cwd, json);
  const configExists = existsSync(configFile);
  if (!configExists) return false;

  const folderPath = getFolderPath(root);
  if (!existsSync(folderPath)) {
    mkdirSync(folderPath, { recursive: true });
  }

  const tsconfigPath = join(cwd, 'tsconfig.json');
  const tsConfigExists = existsSync(tsconfigPath);
  if (!tsConfigExists) return false;

  const tsconfigContent = readFileSync(tsconfigPath, 'utf8');
  const tsconfig = JSON.parse(tsconfigContent);
  const relativePath = relative(process.cwd(), folderPath);

  const checkPaths =
    tsconfig?.compilerOptions?.paths?.[path]?.[0] ===
    `./${relativePath}/*`;

  if (!checkPaths) return false;

  const files = new Set<string>();
  const jsonFile = editJsonFile(configFile);
  (jsonFile.get(PROPERTIES.FILES) as string[])?.forEach(file =>
    files.add(file),
  );

  try {
    createTypesStructure(folderPath, CODEBASE_ANALYSIS).forEach(file =>
      files.add(file),
    );
  } catch {
    console.error(`❌ Error creating the types structure:`);
    return false;
  }

  // Create the .bemedev.json file at the root

  try {
    jsonFile.set(PROPERTIES.FILES, Array.from(files));
    jsonFile.save();
    console.log(`✅ File ${json} rewrited at the root of the project`);
  } catch (error) {
    console.error(`❌ Error rewriting the file ${json}:`, error);
    return false;
  }

  console.log(`🎉 ${bin} soft initialization completed successfully!`);
  return true;
};

